// Confirmation UI: recognition results never apply until the user confirms.
let productRecognitionRevision=0,productRecognitionController=null,productRecognitionCatalog=null,productRecognitionUpload=null;
const productRecognitionDialog=document.createElement('dialog');productRecognitionDialog.id='productRecognitionDialog';productRecognitionDialog.setAttribute('aria-labelledby','productRecognitionTitle');
productRecognitionDialog.innerHTML='<form method="dialog"><button class="recognition-close" aria-label="关闭产品识别">×</button></form><h2 id="productRecognitionTitle">确认产品与工艺</h2><p id="productRecognitionStatus" role="status"></p><div class="recognition-source"><img id="productRecognitionImage" alt="本次上传的A面图片"><div><strong id="productRecognitionLabel"></strong><p id="productRecognitionEvidence"></p></div></div><div class="recognition-fields"><label>产品类别<select id="productRecognitionProduct"><option value="">请选择产品</option></select></label><div id="productRecognitionFields"></div></div><p class="recognition-note">确认后应用所选产品与工艺。未识别的选项保留当前设置；花型、面料质感和拍摄场景仍按你的选择。</p><div class="recognition-actions"><button type="button" id="productRecognitionRetry">重新识别</button><button type="button" id="productRecognitionKeep">保持当前设置</button><button type="button" class="primary" id="productRecognitionConfirm" disabled>确认并应用</button></div>';
document.body.append(productRecognitionDialog);
function cancelProductRecognition(){productRecognitionRevision++;productRecognitionController?.abort();productRecognitionController=null;if(productRecognitionDialog.open)productRecognitionDialog.close();}
globalThis.cancelProductRecognition=cancelProductRecognition;
function productRecognitionCurrent(key,product){if(product==='set')return {duvetCraft:chosenDuvetVariant,sheetStyle:chosenSheetVariant,pillowCraft:chosenPillowVariant}[key];return {quilt:state.quiltSeason,sheet:state.sheetVariant,mat:state.matVariant||state.fabric,mattress:state.mattressVariant,blanket:state.blanketVariant,sleepbag:state.sleepbagVariant,pillowcore:state.pillowcoreVariant}[product];}
function renderProductRecognitionFields(fields={}){
 const product=document.getElementById('productRecognitionProduct').value,item=productRecognitionCatalog?.find(x=>x.id===product),box=document.getElementById('productRecognitionFields');box.replaceChildren();
 for(const group of item?.groups||[]){const label=document.createElement('label');label.append(document.createTextNode(group.name));const select=document.createElement('select');select.dataset.recognitionField=group.key;const unknown=document.createElement('option');unknown.value='';const current=group.choices.find(x=>x.id===productRecognitionCurrent(group.key,product));unknown.textContent='未识别 · 保留当前'+(current?'（'+current.name+'）':'');select.append(unknown);for(const choice of group.choices){const option=document.createElement('option');option.value=choice.id;option.textContent=choice.name;select.append(option);}const field=fields[group.key];if(field&&group.choices.some(x=>x.id===field.id))select.value=field.id;label.append(select);const hint=document.createElement('small');hint.textContent=field?(field.confidence==='medium'?'待确认：':'识别依据：')+field.evidence:'图片中未能确认，可手动选择。';label.append(hint);box.append(label);}
 document.getElementById('productRecognitionConfirm').disabled=!item;
}
function applyProductRecognitionSelection(product,fields,catalog=productRecognitionCatalog){
 if(state.busy)return false;const item=catalog?.find(x=>x.id===product);if(!item)return false;
 for(const group of item.groups)if(fields[group.key]&&!group.choices.some(x=>x.id===fields[group.key]))return false;
 const choices=state.productVariantChoices??={};state.product=product;
 if(product==='set'){if(fields.duvetCraft)chosenDuvetVariant=fields.duvetCraft;if(fields.sheetStyle)chosenSheetVariant=fields.sheetStyle;if(fields.pillowCraft){chosenPillowVariant=fields.pillowCraft;pillowCraftManuallySelected=true;}choices.set=true;}
 else if(product==='mat'){if(fields.variant){state.matVariant=fields.variant;state.fabric=fields.variant;state.fabricMode='selected';}else if(!['ice','rattan','bamboo'].includes(state.fabric)){state.fabric=state.matVariant||'ice';state.fabricMode='selected';}choices.mat=true;}
 else{const key={quilt:'quiltSeason',sheet:'sheetVariant',mattress:'mattressVariant',blanket:'blanketVariant',sleepbag:'sleepbagVariant',pillowcore:'pillowcoreVariant'}[product];if(fields.variant)state[key]=fields.variant;choices[product]=true;if(['sheet','sleepbag'].includes(product)){state.lastMoreProduct=product;choices.sleepbag=true;}}
 const definition=products.find(x=>x.id===product);if(definition&&!definition.fabrics.includes(state.fabric)&&state.textureSource!=='upload'){state.fabric=definition.fabrics[0];state.fabricMode='auto';}
 for(const close of [closeSetVariants,closeMatVariants,closeQuiltVariants,closeSheetVariants,closeMattressVariants,closeBlanketVariants,closeSleepbagVariants,closePillowcoreVariants])close();renderOptions();renderSelections();return true;
}
function paintProductRecognitionResult(upload,catalog,result){
 document.getElementById('productRecognitionImage').src=upload.url;document.getElementById('productRecognitionLabel').textContent=result.label;document.getElementById('productRecognitionStatus').textContent=result.message;document.getElementById('productRecognitionEvidence').textContent=result.product?.evidence||'可手动选择产品与具体工艺。';
 const select=document.getElementById('productRecognitionProduct');select.replaceChildren(new Option('请选择产品',''),...catalog.map(p=>new Option(p.name,p.id)));select.value=result.product?.id||'';renderProductRecognitionFields(result.fields);
}
function showProductRecognitionResult(upload,catalog,result){
 if(!upload||state.upload!==upload||state.busy)return;cancelProductRecognition();productRecognitionUpload=upload;productRecognitionCatalog=catalog;paintProductRecognitionResult(upload,catalog,result);productRecognitionDialog.showModal();
}
async function recognizeUploadedProduct(upload=state.upload){
 if(!upload||state.busy)return;cancelProductRecognition();productRecognitionUpload=upload;const revision=productRecognitionRevision,controller=new AbortController();productRecognitionController=controller;
 const fresh=()=>revision===productRecognitionRevision&&state.upload===upload&&productRecognitionDialog.open;
 const select=document.getElementById('productRecognitionProduct'),retry=document.getElementById('productRecognitionRetry');select.disabled=true;select.replaceChildren(new Option('正在识别…',''));retry.disabled=true;
 document.getElementById('productRecognitionImage').src=upload.url;document.getElementById('productRecognitionLabel').textContent='正在识别产品与具体工艺…';document.getElementById('productRecognitionEvidence').textContent='';document.getElementById('productRecognitionStatus').textContent='分析A面图片，识别完成后请核对产品与工艺。';document.getElementById('productRecognitionFields').replaceChildren();document.getElementById('productRecognitionConfirm').disabled=true;productRecognitionDialog.showModal();
 try{
  if(!productRecognitionCatalog){const r=await fetch('/api/product-recognition/catalog',{signal:controller.signal});const data=await r.json();if(!r.ok)throw Error(data.error||'产品目录暂不可用');productRecognitionCatalog=data.products;}
  if(!fresh())return;const image=new Image();image.src=upload.url;await image.decode();if(!fresh())return;const canvas=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
  const response=await fetch('/api/product-recognition',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image:canvas.toDataURL('image/png')}),signal:controller.signal});const result=await response.json();if(!fresh())return;if(!response.ok)throw Error(result.error||'识别暂不可用');paintProductRecognitionResult(upload,productRecognitionCatalog,result);
 }catch(error){if(!fresh()||error.name==='AbortError')return;document.getElementById('productRecognitionLabel').textContent='请手动确认产品与工艺';document.getElementById('productRecognitionStatus').textContent=error.message;document.getElementById('productRecognitionEvidence').textContent='可重新识别，或手动选择后确认。';select.replaceChildren(new Option('请选择产品',''),...(productRecognitionCatalog||[]).map(p=>new Option(p.name,p.id)));renderProductRecognitionFields();}
 finally{if(fresh()){retry.disabled=false;select.disabled=false;productRecognitionController=null;}}
}
globalThis.recognizeUploadedProduct=recognizeUploadedProduct;
document.getElementById('productRecognitionProduct').onchange=()=>renderProductRecognitionFields();
document.getElementById('productRecognitionKeep').onclick=cancelProductRecognition;
document.getElementById('productRecognitionRetry').onclick=()=>globalThis.recognizeUploadedProduct?.(productRecognitionUpload);
document.getElementById('productRecognitionConfirm').onclick=()=>{if(state.busy)return toast('请等待当前生成完成');const fields=Object.fromEntries([...productRecognitionDialog.querySelectorAll('[data-recognition-field]')].map(x=>[x.dataset.recognitionField,x.value]));if(state.upload!==productRecognitionUpload)return cancelProductRecognition();if(applyProductRecognitionSelection(document.getElementById('productRecognitionProduct').value,fields)){cancelProductRecognition();toast('已应用确认的产品与工艺');}};
productRecognitionDialog.addEventListener('close',()=>{productRecognitionRevision++;productRecognitionController?.abort();productRecognitionController=null;});
const retryRecognitionButton=document.createElement('button');retryRecognitionButton.id='recognizeAProduct';retryRecognitionButton.type='button';retryRecognitionButton.className='recognize-a-product';retryRecognitionButton.textContent='识别产品与工艺';retryRecognitionButton.onclick=()=>recognizeUploadedProduct();document.getElementById('uploadInfo')?.after(retryRecognitionButton);retryRecognitionButton.hidden=!state.upload;
if(document.getElementById('uploadInfo'))new MutationObserver(()=>{retryRecognitionButton.hidden=!state.upload;retryRecognitionButton.disabled=!!state.busy;if(!state.upload&&productRecognitionDialog.open)cancelProductRecognition();}).observe(document.getElementById('uploadInfo'),{attributes:true,attributeFilter:['hidden']});
